// ---------- 多页导航 ----------
  var pages = document.querySelectorAll('.page');
  var navBtns = document.querySelectorAll('nav.pages button');
  var reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  function goto(id) {
    pages.forEach(function (p) {
      var match = p.getAttribute('data-page') === id;
      p.classList.toggle('active', match);
      if (match && !reduceMotion) {
        p.classList.remove('enter');
        void p.offsetWidth; // restart animation
        p.classList.add('enter');
      }
    });
    navBtns.forEach(function (b) { b.classList.toggle('active', b.getAttribute('data-goto') === id); });
    window.scrollTo({ top: 0, behavior: reduceMotion ? 'auto' : 'smooth' });
  }

  document.querySelectorAll('[data-goto]').forEach(function (el) {
    el.addEventListener('click', function () { goto(el.getAttribute('data-goto')); });
  });

  // ---------- 移动端菜单开关 ----------
  var menuToggle = document.getElementById('menu-toggle');
  var pagesNav = document.querySelector('nav.pages');
  if (menuToggle && pagesNav) {
    menuToggle.addEventListener('click', function () {
      pagesNav.classList.toggle('nav-open');
    });
    pagesNav.querySelectorAll('[data-goto]').forEach(function (btn) {
      btn.addEventListener('click', function () { pagesNav.classList.remove('nav-open'); });
    });
  }

  // ---------- 诊断漏斗：点了直接跳页 + 顶部提示条 ----------
  var FUNNEL = {
    newbie: {
      page: 'about',
      text: '你的情况：完全没做过号。建议先看这页搞懂「一人公司」值不值得干，再去 AI 页面看第一步怎么上手。',
      nextLabel: '去看 AI →', nextPage: 'ai'
    },
    stuck: {
      page: 'media',
      text: '你的情况：做了一段时间没起色。先看「文案方法论」找问题出在哪，再去 AI 页面直接抄提示词作业。',
      nextLabel: '去看提示词库 →', nextPage: 'ai'
    },
    scale: {
      page: 'cases',
      text: '你的情况：已经有基础想规模化。先看案例库找参考，想清楚了直接看我的产品。',
      nextLabel: '看我的产品 →', nextPage: 'products'
    }
  };

  document.querySelectorAll('[data-funnel]').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var key = btn.getAttribute('data-funnel');
      var cfg = FUNNEL[key];
      if (!cfg) return;
      goto(cfg.page);
      var banner = document.getElementById('banner-' + cfg.page);
      if (banner) {
        banner.innerHTML =
          '<span class="fb-text">' + cfg.text + ' <button class="fb-next" data-goto="' + cfg.nextPage + '">' + cfg.nextLabel + '</button></span>' +
          '<button class="fb-close" aria-label="关闭">×</button>';
        banner.classList.add('show');
        banner.querySelector('.fb-next').addEventListener('click', function () { goto(cfg.nextPage); });
        banner.querySelector('.fb-close').addEventListener('click', function () { banner.classList.remove('show'); });
      }
    });
  });

  // ---------- 案例库证据图 点击放大 ----------
  var lightbox = document.getElementById('lightbox');
  var lbImg = document.getElementById('lb-img');
  var lbClose = document.getElementById('lb-close');
  document.querySelectorAll('[data-lightbox]').forEach(function (shot) {
    shot.addEventListener('click', function () {
      var img = shot.querySelector('img');
      if (!img) return;
      lbImg.src = img.src;
      lbImg.alt = img.alt;
      lightbox.classList.add('show');
    });
  });
  function closeLightbox() { lightbox.classList.remove('show'); lbImg.src = ''; }
  lbClose.addEventListener('click', closeLightbox);
  lightbox.addEventListener('click', function (e) { if (e.target === lightbox) closeLightbox(); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeLightbox(); });

  // ---------- 我是谁 展开/收起 ----------
  var bioToggle = document.getElementById('bio-toggle');
  var bioMore = document.getElementById('bio-more');
  var bioArrow = document.getElementById('bio-arrow');
  bioToggle.addEventListener('click', function () {
    var showing = bioMore.classList.toggle('show');
    bioToggle.firstChild.textContent = showing ? '收起 ' : '展开完整故事 ';
    bioArrow.textContent = showing ? '↑' : '↓';
  });

