  var grid = document.getElementById('prompt-grid');
  var tabsBox = document.getElementById('prompt-tabs');
  var countBox = document.getElementById('prompt-count');
  var searchBox = document.getElementById('prompt-search');
  var activeModule = 'all';

  function escapeHtml(s) {
    return String(s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  var tabAll = document.createElement('button');
  tabAll.className = 'promptlib-tab active';
  tabAll.textContent = '全部 100';
  tabAll.setAttribute('data-mod', 'all');
  tabsBox.appendChild(tabAll);
  PROMPT_MODULES.forEach(function (mod, mi) {
    var tab = document.createElement('button');
    tab.className = 'promptlib-tab';
    tab.textContent = (mi + 1) + '. ' + mod.module.replace(/（.*）/, '');
    tab.setAttribute('data-mod', mi);
    tabsBox.appendChild(tab);
  });

  function moduleIndexForNum(num) { return Math.floor((num - 1) / 10); }

  PROMPT_FULL.forEach(function (item) {
    var mi = moduleIndexForNum(item.num);
    var card = document.createElement('details');
    card.className = 'prompt-item full entry-d';
    card.setAttribute('data-mod', mi);
    card.setAttribute('data-text', (item.title + item.desc).toLowerCase());
    var toolsHtml = (item.tools || []).map(function (t) { return '<span>' + escapeHtml(t) + '</span>'; }).join('');
    card.innerHTML =
      '<summary><span class="pnum">' + String(item.num).padStart(3, '0') + '</span>' +
      '<span class="ptitle" style="flex:1">' + escapeHtml(item.title) + '<div class="pdesc">' + escapeHtml(item.desc) + '</div></span>' +
      '<span class="entry-arrow"><svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg></span></summary>' +
      '<div class="entry-body">' +
      '<p class="prompt-help">' + escapeHtml(item.help).replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>') + '</p>' +
      '<p class="copy-hint">点一下文本框，全选后复制：</p>' +
      '<textarea class="prompt-textarea" readonly onclick="this.select()">' + escapeHtml(item.prompt) + '</textarea>' +
      '<div class="prompt-tools">' + toolsHtml + '</div>' +
      '</div>';
    grid.appendChild(card);
  });

  function applyFilter() {
    var q = searchBox.value.trim().toLowerCase();
    var visible = 0;
    Array.prototype.forEach.call(grid.children, function (card) {
      var modOk = activeModule === 'all' || card.getAttribute('data-mod') === String(activeModule);
      var textOk = !q || card.getAttribute('data-text').indexOf(q) !== -1;
      var show = modOk && textOk;
      card.classList.toggle('hidden', !show);
      if (show) visible++;
    });
    countBox.textContent = '显示 ' + visible + ' / 100';
  }

  tabsBox.addEventListener('click', function (e) {
    var btn = e.target.closest('.promptlib-tab');
    if (!btn) return;
    Array.prototype.forEach.call(tabsBox.children, function (b) { b.classList.remove('active'); });
    btn.classList.add('active');
    activeModule = btn.getAttribute('data-mod');
    applyFilter();
  });
  searchBox.addEventListener('input', applyFilter);
  applyFilter();

  // ---------- AI名词库 ----------
  var TERM_MODULES = [{"cat": "基础概念", "items": [{"term": "大模型（LLM）", "brief": "一个吃过全世界几乎所有公开文字（书籍、网页、对话记录）训练出来的AI程序，靠“预测下一个字最可能是什么”来生成语言，本质是概率游戏，不是真的“理解”了世界。", "analogy": "像一个把图书馆所有书都读了一遍、但没做过一天真实工作的天才实习生——知识面广到吓人，但没有真实世界的经验，你交代任务的方式（提示词）直接决定他干活的质量。", "usage": "你现在用的ChatGPT、Claude、豆包、Kimi，聊天框背后跑的都是大模型。写文案时它给你的每一句话，都是“猜”出来最可能符合你要求的下一个字，一个字一个字接龙接出来的——这就是为什么你换个说法问，答案质量能差很多：你在训练“猜”的方向。", "misconception": "很多人以为大模型是“查数据库”，其实它训练完之后脑子里没有存一份“事实清单”，它只是学会了语言的统计规律，这也是为什么它会一本正经编答案（见“幻觉”词条）。"}, {"term": "Token（词元）", "brief": "AI处理文字时，先把你的话切成一小块一小块的“词元”，再一块一块地读和生成，不是整句话一起处理的。", "analogy": "像自动收银机扫商品——不是把购物车整个塞进扫描器，是一件一件扫过去累加。AI“读”你的话和“写”回答，都是按token一个一个来的。", "usage": "中文一个字大概算1-2个token，英文一个词大概算1个token。你付费用API、或者免费额度用完的提示——扣的都是token数，不是字数。写长逐字稿或长文章时如果AI开始“断片”忘记前面说的设定，很可能是token攒太多超过了它这次对话能记住的上限（见“上下文窗口”词条）。"}, {"term": "参数", "brief": "训练时被反复调整、最终决定AI“怎么想”的一堆数字，规模越大通常意味着模型见过的规律越复杂，能力上限越高，但跑起来更贵更慢。", "analogy": "像一个人大脑里神经元之间的连接强度，参数多不等于一定聪明，但确实是“能装下多少复杂规律”的物理上限。", "usage": "你刷到的新闻说“某模型700亿参数”“某模型万亿参数”，理解成“这个模型的脑容量级别”就够用了，不需要真的懂数学。做选题时可以拿这个当谈资——“参数越大不代表体验越好，很多时候小模型+好提示词反而更好用”，这本身就是个能打的观点。"}, {"term": "上下文窗口", "brief": "AI这一次对话里，能同时“看到”多少内容——包括你说过的话、它自己回答过的话，全部加起来的上限。", "analogy": "像一张能摊开工作的桌子，桌子越大，能同时铺开的资料越多；一旦资料超出桌面，最早放上去的那些就得先收起来，AI也是这样，早期设定可能被“挤”没了。", "usage": "你在跟AI来回改一篇长文章、或者喂给它一整篇逐字稿要它拆解，改到后面它突然“忘了”你最开始定的调性——大概率就是超出上下文窗口了。解决办法：把最重要的设定放在最新一轮对话里再强调一遍，或者干脆开一个新对话重新喂关键信息，不要死磕一个已经很长的对话。"}, {"term": "训练 vs 推理", "brief": "训练是AI公司花几个月、烧掉巨额算力，让模型从海量数据里“学”出规律的过程；推理是这个训练好的模型被你实际拿来用、回答你问题的过程。", "analogy": "训练像运动员常年封闭集训，推理像上场比赛那一刻——集训好不好，直接决定比赛表现，但集训本身你看不到，你只会看到比赛（也就是你跟AI对话时的表现）。", "usage": "你每次打开ChatGPT提问，用的都是“推理”，跟你没有任何关系的成本；“训练”的成本是模型公司自己扛的，跟AI公司裁员、融资这些新闻里提到的“训练成本”是一回事，看得懂新闻就行，不用纠结自己有没有份。"}, {"term": "多模态", "brief": "AI不再只会处理文字，现在能同时看图、听声音、生成图片和视频，一个模型多种感官。", "analogy": "以前的AI像只能收发文字的笔友，现在的AI更像视频通话的朋友——能看你发的图、听你的语音、也能画图回你。", "usage": "你截一张同行的爆款封面图问AI“这个封面为什么吸引人”，或者让AI直接把你的文字脚本生成分镜草图，用的都是多模态能力。这也是为什么现在很多AI工具直接能做“文字转视频”，背后是同一个模型既懂文字又懂画面。"}]}, {"cat": "交互方式", "items": [{"term": "Prompt（提示词）", "brief": "你写给AI的那句指令，措辞、结构、给不给例子，直接决定AI这次给你的答案是能用还是废稿。", "analogy": "像点菜时跟厨师说清楚“不要香菜、微辣、装盘好看点”——你说得越具体，端上来的菜越贴近你想要的，含糊地说“随便做点好吃的”，大概率踩雷。", "usage": "这是你天天在用、但可能没意识到自己在“设计”的东西。同一个选题，“帮我写个短视频脚本”和“帮我写一个抖音口播脚本，开头要用反差感钩子，中间插一句转折提醒，结尾不要喊点关注”——后者出来的东西直接能用，前者大概率还要改三遍。"}, {"term": "System Prompt（系统提示词）", "brief": "藏在对话最前面、你平时看不到的一段“角色设定”，规定AI这次要扮演谁、遵守什么规矩，比你后面说的每一句话优先级都高、影响更持久。", "analogy": "像演员开拍前拿到的角色小传——观众只看到演员的表演，看不到那份小传，但演员全程按小传里定的性格、说话方式在演。", "usage": "本站“提示词库”里那些几百字的长提示词（比如HUMAN 3.0框架、查理芒格顾问），本质都是系统提示词，你复制粘贴进AI对话框第一句发出去，之后AI就会一直按这个设定的角色和你聊，不用每句话都重新解释你要什么。"}, {"term": "多轮对话", "brief": "AI能记住你们这次对话里之前说过的内容，一步步往下聊，不用每句话都从头交代背景。", "analogy": "像跟一个记性好的朋友聊天——你说过的事他不会转头就忘，你可以直接说“接着刚才那个”，不用重新解释一遍。", "usage": "写稿子最实用的方式不是一次性让AI“写一篇完整文章”，是先让它理解你的选题和角度，你看完提反馈，它再改一版——这种一步步调整，靠的就是多轮对话的记忆能力，比一次性甩需求效果好很多。"}, {"term": "Temperature（创造力调节）", "brief": "控制AI“回答有多敢天马行空”的一个参数，数值调低答案更保守规矩，调高更有创意但也更容易前后不一致甚至跑偏。", "analogy": "像做菜的火候——小火炖出来的菜规规矩矩没什么惊喜，大火爆炒可能出彩、也可能直接糊锅，你得根据场景选合适的火候。", "usage": "普通聊天工具的网页界面一般不给你调这个，但用API或者一些进阶工具（比如设置了“创意模式”“严谨模式”的应用）会看到这个选项——写有创意的开头钩子可以调高一点，写需要严谨核对的数据类内容建议调低。"}]}, {"cat": "进阶概念", "items": [{"term": "Agent（智能体）", "brief": "不只是回答问题，还能自己拆解任务、调用工具、连续执行多个步骤直到完成目标的AI——比自己上网查资料、自己操作软件、自己判断下一步该干什么。", "analogy": "从“只会出主意的参谋”升级成“能自己带兵打仗的将军”——你说要什么结果，它自己规划怎么一步步做到。", "usage": "Claude Code就是一种智能体，你说“帮我把这篇文章的配图截图找好、裁好、嵌进正文里”，它会自己打开浏览器截图、裁图、写代码嵌进HTML，中间不用你一步步教它怎么操作。做自媒体如果开始用智能体类工具，效率提升不是“快一点”，是“这件事本来要你自己动手三十分钟，现在你说一句话就行”。"}, {"term": "MCP（模型上下文协议）", "brief": "一套让AI能连接外部工具和数据（你的文件、飞书、浏览器、数据库……）的通用接口标准，2024年底Anthropic提出，现在已经成了行业公认的“AI连接万物”的方式。", "analogy": "像给AI装了一套万能插座——以前不同的AI工具想连不同的软件，都要单独开发一套接口，现在有了统一标准，插上就能用，装修成本大幅降低。", "usage": "本站背后帮你截图、存文件、发消息这些能力，都是靠MCP这类协议把AI和外部工具打通实现的。你不需要自己懂怎么开发，但理解这个词能帮你判断一个AI工具“能不能真正帮你干活”——如果它支持MCP或者类似的插件/工具调用能力，说明它不只是聊天机器人，是能真正动手操作的助理。"}, {"term": "RAG（检索增强生成）", "brief": "让AI回答问题之前，先去查一份真实资料库或者搜索结果，再基于查到的内容组织答案，而不是完全凭训练时“记住”的内容硬答。", "analogy": "像开卷考试和闭卷考试的区别——闭卷全靠脑子里记的东西答题，容易记错、记漏；开卷可以先翻书查证，答案明显更靠谱。", "usage": "这是减少AI“一本正经胡说八道”最有效的技术手段之一。你用的一些AI工具带“联网搜索”开关，打开之后AI会先搜一圈再回答，这就是RAG的一种应用；写需要真实数据支撑的内容（比如涉及具体数字、最新政策），优先选带这类联网/检索功能的工具或者自己手动核实，别指望AI凭“记忆”给你准确数字。"}, {"term": "Function Calling（工具调用）", "brief": "AI在聊天过程中判断“这件事我自己算不准、办不到”，于是主动去调用一个具体的外部工具（计算器、搜索引擎、日历、下单系统）来完成，再把结果组织成人话回给你。", "analogy": "像你自己心算不出复杂的乘法，主动掏出计算器按一下——工具调用就是AI给自己“配了个计算器”这类外部帮手。", "usage": "你问AI“今天天气怎么样”，它自己脑子里没有实时天气数据，会自动调用一个天气查询工具，查完再告诉你——这个过程你可能根本没注意到，但背后就是工具调用在起作用。理解这个词的意义在于：AI能力的边界不是它“脑子里装了多少”，是它“能调用多少外部工具”，这也是为什么智能体类产品发展得这么快。"}, {"term": "微调（Fine-tuning）", "brief": "在一个已经训练好、什么都懂一点的通用大模型基础上，再用你自己的专属数据“补课”，让它更懂你这个特定领域或者更贴近你的说话风格。", "analogy": "像请一个什么都懂一点的通才家教，再单独把你们家孩子的教材塞给他重点补习——底子是通用的，补课让他更贴合你的具体需求。", "usage": "普通人做自媒体基本用不上，这是模型公司或者有技术团队的企业才会做的事，一般是拿来训练“专门写某个品牌调性文案”“专门懂某个垂直行业知识”的定制AI。你看到这个词，理解成“AI界的定制西装”就行，知道意思即可，不用真的自己去操作。"}, {"term": "Embedding（嵌入向量）", "brief": "AI把一段文字“翻译”成一串数字（向量），这串数字能代表这段话的语义，方便计算机用数学方法判断两段话意思像不像。", "analogy": "像给每一句话拍一张“指纹照”——指纹越接近的两句话，意思也越接近，计算机不需要真的“读懂”语言，靠比对这串数字就能判断相似度。", "usage": "你用一些工具做“相似内容检索”（比如输入一段话，找出你历史发过的类似选题）、或者做“语义搜索”（不是关键词精确匹配，是意思相近就能搜到），背后都是嵌入向量在起作用。这个词偏技术，普通自媒体人不需要真的懂原理，知道“AI比对文字相似度靠的是这个”就够用。"}]}, {"cat": "行业热词", "items": [{"term": "AGI（通用人工智能）", "brief": "能像人一样，几乎任何智力任务都能干得不比人差的AI，目前全世界都还没真正做到，是整个行业追逐的终极目标，不是已经实现的东西。", "analogy": "现在的AI更像“某个领域的资深专家”，AGI则是“什么都会、随时能上手任何新领域的全才”，两者中间的差距，业内公认还很大。", "usage": "新闻和短视频标题里经常拿“AGI要来了”“距离AGI还有多远”当噱头博眼球，你看到这类标题，理解成“还是个没实现的目标，媒体在制造焦虑感”就行，别被带节奏，这本身也是个能拿来做内容的反向选题角度——“别被AGI焦虑营销割了”。"}, {"term": "幻觉（Hallucination）", "brief": "AI一本正经地编造错误信息、给不存在的数据、引用不存在的来源，讲得跟真的一样，语气里没有任何“我不确定”的信号。", "analogy": "像一个记性不太好、但特别自信、从不说“我不知道”的朋友——你问他一个他其实不清楚的事，他也会给你编一个听起来很合理的答案。", "usage": "这是本站反复强调“AI写的内容涉及具体数据和事实必须自己核实”这条规则的根本原因——AI不是故意骗你，它的工作原理决定了它会“编”，而且编得很自信，你如果照抄不查，出了事故只能自己背锅。"}, {"term": "对齐（Alignment）", "brief": "让AI的行为符合人类的意图和价值观、不去做人类不希望它做的事，是AI安全研究里最核心的课题之一。", "analogy": "像给一个能力很强的新员工做入职培训——光有能力不够，还得让他明白公司的底线和规矩，不然能力越强，捅的篓子可能越大。", "usage": "你用AI聊天时，遇到它“拒绝回答某些问题”或者主动加一句“请注意XX”这类安全提示，这就是对齐机制在起作用。新闻里“某公司投入巨资做AI安全对齐研究”，说的就是这件事，理解了这个词，就懂为什么AI有时候看起来“很谨慎甚至有点啰嗦”。"}, {"term": "开源 vs 闭源", "brief": "开源模型把训练好的参数公开出来，谁都能下载到自己的电脑或服务器上跑、甚至自己改造；闭源模型只能通过官方提供的网页或接口调用，看不到也拿不到内部的东西。", "analogy": "开源像公开的菜谱——谁都能照着做，还能自己改良配方；闭源像餐厅只卖成品菜，你能吃到，但拿不走配方，也没法在家复刻。", "usage": "ChatGPT、Claude是闭源的，你只能通过官网或者API用；DeepSeek、Llama、Qwen这类可以下载到本地跑的，是开源的。对普通自媒体人来说这个区别影响不大（大部分人都是用网页版），但如果你身边有技术团队想做“完全私有、数据不出公司”的AI应用，开源模型就是绕不开的选项。"}, {"term": "Benchmark（跑分/基准测试）", "brief": "用一整套标准化的题目和任务，给不同的AI模型做“考试”，用分数量化比较谁的能力更强。", "analogy": "像各类模拟考的排名榜——但要留意，“考得好”不完全等于“你实际用起来顺手”，跑分题目和你日常真实需求之间未必完全对应。", "usage": "新闻标题说“某新模型跑分超越GPT”，理解成“某个标准化考试考赢了对手”就够用，别神化这个数字——选AI工具的时候，自己实际试用两天感受出来的顺手程度，往往比跑分榜单更有参考价值，这也是本站“AI工具库”栏目每个工具都标“擅长什么”而不是只堆跑分的原因。"}, {"term": "算力 / GPU", "brief": "训练和运行AI模型需要的“计算能力”，主要靠一种叫GPU（图形处理器，最初是给游戏显卡设计的芯片）来提供，是整个AI行业最硬核也最烧钱的底层资源。", "analogy": "算力就是AI公司的“电力”，GPU就是发电站——谁的发电站多、发电效率高，谁就能训出更强、跑得更快的模型，这也是为什么英伟达（做GPU的公司）这几年市值一路狂飙。", "usage": "新闻里“英伟达GPU一卡难求”“某国被卡脖子买不到高端芯片”，说的都是这个——算力已经变成AI时代堪比石油的战略资源。这个词你不需要真的懂芯片原理，理解成“AI烧的不是电，是天价显卡”，能帮你看懂大半的AI行业新闻。"}]}];

  var termGrid = document.getElementById('term-grid');
  var termTabsBox = document.getElementById('term-tabs');
  var termCountBox = document.getElementById('term-count');
  var termSearchBox = document.getElementById('term-search');
  var activeTermCat = 'all';
  var termTotal = 0;

  var termTabAll = document.createElement('button');
  termTabAll.className = 'promptlib-tab active';
  termTabAll.setAttribute('data-cat', 'all');
  termTabsBox.appendChild(termTabAll);
  TERM_MODULES.forEach(function (mod) {
    var tab = document.createElement('button');
    tab.className = 'promptlib-tab';
    tab.textContent = mod.cat;
    tab.setAttribute('data-cat', mod.cat);
    termTabsBox.appendChild(tab);
  });

  TERM_MODULES.forEach(function (mod) {
    mod.items.forEach(function (item) {
      termTotal++;
      var card = document.createElement('details');
      card.className = 'prompt-item full entry-d';
      card.setAttribute('data-cat', mod.cat);
      card.setAttribute('data-text', (item.term + item.brief).toLowerCase());
      card.innerHTML =
        '<summary><span class="ptitle" style="flex:1">' + escapeHtml(item.term) + '<div class="pdesc">' + escapeHtml(item.brief) + '</div></span>' +
        '<span class="entry-arrow"><svg viewBox="0 0 24 24" fill="none" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="9 18 15 12 9 6"></polyline></svg></span></summary>' +
        '<div class="entry-body">' +
        '<p><b style="color:var(--ink);">类比：</b>' + escapeHtml(item.analogy) + '</p>' +
        '<p><b style="color:var(--ink);">自媒体场景怎么用得上：</b>' + escapeHtml(item.usage) + '</p>' +
        (item.misconception ? '<p><b style="color:var(--accent);">常见误区：</b>' + escapeHtml(item.misconception) + '</p>' : '') +
        '</div>';
      termGrid.appendChild(card);
    });
  });
  termTabAll.textContent = '全部 ' + termTotal;

  function applyTermFilter() {
    var q = termSearchBox.value.trim().toLowerCase();
    var visible = 0;
    Array.prototype.forEach.call(termGrid.children, function (card) {
      var catOk = activeTermCat === 'all' || card.getAttribute('data-cat') === activeTermCat;
      var textOk = !q || card.getAttribute('data-text').indexOf(q) !== -1;
      var show = catOk && textOk;
      card.classList.toggle('hidden', !show);
      if (show) visible++;
    });
    termCountBox.textContent = '显示 ' + visible + ' / ' + termTotal;
  }
  termTabsBox.addEventListener('click', function (e) {
    var btn = e.target.closest('.promptlib-tab');
    if (!btn) return;
    Array.prototype.forEach.call(termTabsBox.children, function (b) { b.classList.remove('active'); });
    btn.classList.add('active');
    activeTermCat = btn.getAttribute('data-cat');
    applyTermFilter();
  });
  termSearchBox.addEventListener('input', applyTermFilter);
  applyTermFilter();

  // ---------- AI工具库 ----------
  var toolGrid = document.getElementById('tool-grid');
  var toolTabsBox = document.getElementById('tool-tabs');
  var toolCountBox = document.getElementById('tool-count');
  var toolSearchBox = document.getElementById('tool-search');
  var activeToolCat = 'all';
  var toolCards = Array.prototype.slice.call(toolGrid.children);
  var toolTotal = toolCards.length;
  var toolCats = [];
  toolCards.forEach(function (card) {
    var c = card.getAttribute('data-cat');
    if (toolCats.indexOf(c) === -1) toolCats.push(c);
  });

  var toolTabAll = document.createElement('button');
  toolTabAll.className = 'promptlib-tab active';
  toolTabAll.textContent = '全部 ' + toolTotal;
  toolTabAll.setAttribute('data-cat', 'all');
  toolTabsBox.appendChild(toolTabAll);
  toolCats.forEach(function (c) {
    var tab = document.createElement('button');
    tab.className = 'promptlib-tab';
    tab.textContent = c;
    tab.setAttribute('data-cat', c);
    toolTabsBox.appendChild(tab);
  });

  function applyToolFilter() {
    var q = toolSearchBox.value.trim().toLowerCase();
    var visible = 0;
    toolCards.forEach(function (card) {
      var catOk = activeToolCat === 'all' || card.getAttribute('data-cat') === activeToolCat;
      var textOk = !q || (card.getAttribute('data-text') + card.querySelector('.tool-name').textContent).toLowerCase().indexOf(q) !== -1;
      var show = catOk && textOk;
      card.classList.toggle('hidden', !show);
      if (show) visible++;
    });
    toolCountBox.textContent = '显示 ' + visible + ' / ' + toolTotal;
  }
  toolTabsBox.addEventListener('click', function (e) {
    var btn = e.target.closest('.promptlib-tab');
    if (!btn) return;
    Array.prototype.forEach.call(toolTabsBox.children, function (b) { b.classList.remove('active'); });
    btn.classList.add('active');
    activeToolCat = btn.getAttribute('data-cat');
    applyToolFilter();
  });
  toolSearchBox.addEventListener('input', applyToolFilter);
  applyToolFilter();

  // ---------- AI页 侧边栏：点击滚动 + 高亮 ----------
  var aiSideLinks = Array.prototype.slice.call(document.querySelectorAll('#ai-side-nav a'));
  aiSideLinks.forEach(function (link) {
    link.addEventListener('click', function (e) {
      e.preventDefault();
      var target = document.getElementById(link.getAttribute('data-sec'));
      if (!target) return;
      aiSideLinks.forEach(function (l) { l.classList.remove('active'); });
      link.classList.add('active');
      var top = target.getBoundingClientRect().top + window.pageYOffset - 78;
      window.scrollTo(0, top);
    });
  });
  if ('IntersectionObserver' in window) {
    var aiSpy = new IntersectionObserver(function (entries) {
      entries.forEach(function (entry) {
        if (!entry.isIntersecting) return;
        aiSideLinks.forEach(function (l) {
          l.classList.toggle('active', l.getAttribute('data-sec') === entry.target.id);
        });
      });
    }, { rootMargin: '-20% 0px -70% 0px' });
    ['ai-sec-terms', 'ai-sec-tools', 'ai-sec-apply'].forEach(function (id) {
      var el = document.getElementById(id);
      if (el) aiSpy.observe(el);
    });
  }
